// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {RewardVault} from "../src/RewardVault.sol";

contract InvMutTest is Test {
    RewardVault c;
    function setUp() public { c = new RewardVault(); }
    function testFuzz_property(uint256 newRate, uint256 depositAmount) public {
        newRate = bound(newRate, 1, type(uint128).max);
        depositAmount = bound(depositAmount, 1, 1 ether);

        vm.prank(c.owner());
        c.setRewardRate(newRate);

        address user = address(0x100);
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.deposit{value: depositAmount}();

        uint256 rewardBefore = c.reward(user);
        vm.prank(user);
        c.claim();
        uint256 rewardAfter = c.reward(user);

        assertTrue(rewardAfter - rewardBefore == depositAmount * newRate);
    }
}
